// deploy/dokploy/render-config.sh turns GUARD_AGENT_* / GUARD_SANDBOX_IMAGE /
// GUARD_THRESHOLDS_MODE into agents.toml and thresholds.toml, unless the app
// checkout commits its own. Every test runs the real script with /bin/sh.
//
// The tests that hand a generated file to guard's own parsers need a guard
// binary: set GUARD_BIN to its path. Without it they are skipped.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { repoRoot } from './compose-text.mjs';

const SCRIPT = join(repoRoot, 'deploy', 'dokploy', 'render-config.sh');
const GUARD_BIN = process.env.GUARD_BIN;
const needsGuard = GUARD_BIN ? {} : { skip: 'set GUARD_BIN to a guard binary' };
const IMAGE = `ghcr.io/acme/guard-sandbox@sha256:${'a'.repeat(64)}`;
/** The smallest environment that renders both files. */
const VALID = {
  GUARD_AGENT_MODEL: 'claude-opus-5-5',
  GUARD_AGENT_BUDGET_USD: '5',
  GUARD_AGENT_DAILY_USD_CAP: '50',
  GUARD_SANDBOX_IMAGE: IMAGE,
  GUARD_THRESHOLDS_MODE: 'active',
};

/** A scratch checkout and output directory, removed when the test ends. */
function scratch(t) {
  const dir = mkdtempSync(join(tmpdir(), 'guard-render-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const checkout = join(dir, 'checkout');
  const out = join(dir, 'config');
  mkdirSync(checkout);
  return { dir, checkout, out };
}

function render({ checkout, out }, env) {
  return spawnSync('/bin/sh', [SCRIPT, checkout, out], {
    env: { PATH: process.env.PATH, ...env },
    encoding: 'utf8',
  });
}

const without = (name) => Object.fromEntries(Object.entries(VALID).filter(([key]) => key !== name));
const text = (dir, name) => readFileSync(join(dir, name), 'utf8');
/** A file without its leading comment lines. */
const body = (content) => content.replace(/^(?:#.*\n)+/, '');

const DEFAULT_AGENTS = `version = 1

[gateway]
url = "http://litellm:4000"
master_key_env = "LITELLM_MASTER_KEY"

[roles]
qa = "qa"
coder = "coder"

[agents.qa]
role = "qa"
runtime = "claude-code"
model = "claude-opus-5-5"
budget_usd = 5.0

[agents.coder]
role = "coder"
runtime = "claude-code"
model = "claude-opus-5-5"
budget_usd = 5.0

[scheduler]
host_slots = 1
daily_usd_cap = 50.0
image = "${IMAGE}"
`;

test('renders agents.toml from the required variables, with the documented defaults', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, VALID);
  assert.equal(run.status, 0, run.stderr);
  assert.equal(run.stderr, '');
  const agents = text(dirs.out, 'agents.toml');
  assert.match(agents, /^# Generated by /);
  assert.equal(body(agents), DEFAULT_AGENTS);
  assert.match(run.stdout, /agents\.toml: generated/);
});

test('a per-role model, the runtime, the budget, the cap and the slots come from their variables', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, {
    ...VALID,
    GUARD_AGENT_RUNTIME: 'mini-swe-agent',
    GUARD_AGENT_MODEL: 'openai/gpt-5',
    GUARD_AGENT_QA_MODEL: 'anthropic/claude-sonnet-4-5',
    GUARD_AGENT_CODER_MODEL: 'gemini/gemini-2.5-pro',
    GUARD_AGENT_BUDGET_USD: '2.5',
    GUARD_AGENT_DAILY_USD_CAP: '120.75',
    GUARD_AGENT_HOST_SLOTS: '4',
  });
  assert.equal(run.status, 0, run.stderr);
  const agents = text(dirs.out, 'agents.toml');
  assert.equal([...agents.matchAll(/^runtime = "mini-swe-agent"$/gm)].length, 2);
  assert.match(agents, /\[agents\.qa\]\nrole = "qa"\nruntime = "mini-swe-agent"\nmodel = "anthropic\/claude-sonnet-4-5"\nbudget_usd = 2\.5\n/);
  assert.match(agents, /\[agents\.coder\]\nrole = "coder"\nruntime = "mini-swe-agent"\nmodel = "gemini\/gemini-2\.5-pro"\nbudget_usd = 2\.5\n/);
  assert.match(agents, /^host_slots = 4\ndaily_usd_cap = 120\.75$/m);
});

test('one per-role model falls back to the default model for the other role', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, { ...VALID, GUARD_AGENT_CODER_MODEL: 'anthropic/claude-sonnet-4-5' });
  assert.equal(run.status, 0, run.stderr);
  const agents = text(dirs.out, 'agents.toml');
  assert.match(agents, /\[agents\.qa\][^[]*model = "claude-opus-5-5"\n/);
  assert.match(agents, /\[agents\.coder\][^[]*model = "anthropic\/claude-sonnet-4-5"\n/);
});

test('an empty optional variable counts as unset', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, {
    ...VALID,
    GUARD_AGENT_RUNTIME: '',
    GUARD_AGENT_QA_MODEL: '',
    GUARD_AGENT_CODER_MODEL: '',
    GUARD_AGENT_HOST_SLOTS: '',
  });
  assert.equal(run.status, 0, run.stderr);
  assert.equal(body(text(dirs.out, 'agents.toml')), DEFAULT_AGENTS);
});

for (const mode of ['shadow', 'active']) {
  test(`renders thresholds.toml with mode ${mode}`, (t) => {
    const dirs = scratch(t);
    const run = render(dirs, { ...VALID, GUARD_THRESHOLDS_MODE: mode });
    assert.equal(run.status, 0, run.stderr);
    const thresholds = text(dirs.out, 'thresholds.toml');
    assert.match(thresholds, /^# Generated by /);
    assert.equal(body(thresholds), `version = 1\nmode = "${mode}"\n`);
    assert.match(run.stdout, /thresholds\.toml: generated/);
  });
}

test('an agents.toml committed in the checkout wins over the variables', (t) => {
  const dirs = scratch(t);
  const committed = '# the team owns this file\nversion = 1\n';
  writeFileSync(join(dirs.checkout, 'agents.toml'), committed);
  // The agent variables are not even read: bad values do not matter.
  const run = render(dirs, { GUARD_THRESHOLDS_MODE: 'shadow', GUARD_AGENT_BUDGET_USD: 'not-a-number' });
  assert.equal(run.status, 0, run.stderr);
  assert.equal(text(dirs.out, 'agents.toml'), committed);
  assert.match(run.stdout, /agents\.toml: using the one committed/);
  assert.equal(body(text(dirs.out, 'thresholds.toml')), 'version = 1\nmode = "shadow"\n');
});

test('a thresholds.toml committed in the checkout wins over GUARD_THRESHOLDS_MODE', (t) => {
  const dirs = scratch(t);
  const committed = 'version = 1\nmode = "shadow"\nagent_suitable_min = 0.9\n';
  writeFileSync(join(dirs.checkout, 'thresholds.toml'), committed);
  const run = render(dirs, { ...VALID, GUARD_THRESHOLDS_MODE: 'not-a-mode' });
  assert.equal(run.status, 0, run.stderr);
  assert.equal(text(dirs.out, 'thresholds.toml'), committed);
  assert.match(run.stdout, /thresholds\.toml: using the one committed/);
  assert.equal(body(text(dirs.out, 'agents.toml')), DEFAULT_AGENTS);
});

test('a file committed after a generated run replaces the generated copy', (t) => {
  const dirs = scratch(t);
  assert.equal(render(dirs, VALID).status, 0);
  assert.match(text(dirs.out, 'agents.toml'), /^# Generated by /);
  const committed = 'version = 1\n# committed later\n';
  writeFileSync(join(dirs.checkout, 'agents.toml'), committed);
  assert.equal(render(dirs, VALID).status, 0);
  assert.equal(text(dirs.out, 'agents.toml'), committed);
});

// One failing case per variable and rule: the start stops and the message
// names the variable.
const INVALID = [
  ['GUARD_AGENT_MODEL', undefined, 'missing'],
  ['GUARD_AGENT_MODEL', '', 'empty'],
  ['GUARD_AGENT_MODEL', 'claude"\nmodel = "x', 'a value that would break out of the TOML string'],
  ['GUARD_AGENT_MODEL', 'claude opus', 'a space'],
  ['GUARD_AGENT_MODEL', 'openai/gpt-5', 'not a Claude model for runtime claude-code'],
  ['GUARD_AGENT_QA_MODEL', 'openai/gpt-5', 'not a Claude model for runtime claude-code'],
  ['GUARD_AGENT_CODER_MODEL', 'gemini/gemini-2.5-pro', 'not a Claude model for runtime claude-code'],
  ['GUARD_AGENT_CODER_MODEL', "claude'opus", 'a quote'],
  ['GUARD_AGENT_RUNTIME', 'claude', 'an unknown runtime'],
  ['GUARD_AGENT_RUNTIME', 'fake', 'the test-only runtime'],
  ['GUARD_AGENT_BUDGET_USD', undefined, 'missing'],
  ['GUARD_AGENT_BUDGET_USD', '0', 'zero'],
  ['GUARD_AGENT_BUDGET_USD', '0.00', 'zero with decimals'],
  ['GUARD_AGENT_BUDGET_USD', '-5', 'negative'],
  ['GUARD_AGENT_BUDGET_USD', '5usd', 'not a number'],
  ['GUARD_AGENT_BUDGET_USD', '1e3', 'an exponent'],
  ['GUARD_AGENT_DAILY_USD_CAP', undefined, 'missing'],
  ['GUARD_AGENT_DAILY_USD_CAP', '0', 'zero'],
  ['GUARD_AGENT_DAILY_USD_CAP', 'fifty', 'not a number'],
  ['GUARD_AGENT_HOST_SLOTS', '0', 'zero'],
  ['GUARD_AGENT_HOST_SLOTS', '1.5', 'not an integer'],
  ['GUARD_AGENT_HOST_SLOTS', 'two', 'not a number'],
  ['GUARD_SANDBOX_IMAGE', undefined, 'missing'],
  ['GUARD_SANDBOX_IMAGE', 'ghcr.io/acme/guard-sandbox:latest', 'a tag instead of a digest'],
  ['GUARD_SANDBOX_IMAGE', `ghcr.io/acme/guard-sandbox@sha256:${'A'.repeat(64)}`, 'an upper-case digest'],
  ['GUARD_SANDBOX_IMAGE', `ghcr.io/acme/guard-sandbox@sha256:${'a'.repeat(63)}`, 'a short digest'],
  ['GUARD_SANDBOX_IMAGE', `@sha256:${'a'.repeat(64)}`, 'no repository'],
  ['GUARD_THRESHOLDS_MODE', undefined, 'missing'],
  ['GUARD_THRESHOLDS_MODE', 'on', 'not a mode'],
  ['GUARD_THRESHOLDS_MODE', 'Active', 'the wrong case'],
];

for (const [name, value, why] of INVALID) {
  test(`${name}: ${why} stops the start and names the variable`, (t) => {
    const dirs = scratch(t);
    const env = value === undefined ? without(name) : { ...VALID, [name]: value };
    const run = render(dirs, env);
    assert.equal(run.status, 2, `stdout: ${run.stdout}\nstderr: ${run.stderr}`);
    const errors = run.stderr.split('\n').filter((line) => line.startsWith('error: '));
    assert.equal(errors.length, 1, run.stderr);
    assert.ok(errors[0].startsWith(`error: ${name}: `), errors[0]);
    assert.ok(!existsSync(dirs.out) || readdirSync(dirs.out).length === 0, 'nothing is written');
  });
}

test('every bad variable is reported in one run', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, { GUARD_AGENT_MODEL: 'claude-opus-5-5', GUARD_AGENT_HOST_SLOTS: '0' });
  assert.equal(run.status, 2);
  const named = run.stderr
    .split('\n')
    .map((line) => /^error: ([A-Z_]+): /.exec(line)?.[1])
    .filter(Boolean);
  assert.deepEqual(named.sort(), [
    'GUARD_AGENT_BUDGET_USD',
    'GUARD_AGENT_DAILY_USD_CAP',
    'GUARD_AGENT_HOST_SLOTS',
    'GUARD_SANDBOX_IMAGE',
    'GUARD_THRESHOLDS_MODE',
  ]);
});

test('a failed run leaves the files of the previous run untouched', (t) => {
  const dirs = scratch(t);
  assert.equal(render(dirs, VALID).status, 0);
  const before = [text(dirs.out, 'agents.toml'), text(dirs.out, 'thresholds.toml')];
  const run = render(dirs, { ...VALID, GUARD_AGENT_MODEL: 'openai/gpt-5', GUARD_THRESHOLDS_MODE: 'shadow' });
  assert.equal(run.status, 2);
  assert.deepEqual([text(dirs.out, 'agents.toml'), text(dirs.out, 'thresholds.toml')], before);
  assert.deepEqual(readdirSync(dirs.out).sort(), ['agents.toml', 'thresholds.toml']);
});

test('a secret-looking value is never echoed back', (t) => {
  const dirs = scratch(t);
  const run = render(dirs, { ...VALID, GUARD_AGENT_MODEL: 'sk-ant-oat01 pasted by mistake' });
  assert.equal(run.status, 2);
  assert.doesNotMatch(run.stdout + run.stderr, /sk-ant-oat01/);
});

test('the script needs the checkout and the output directory as arguments', (t) => {
  const dirs = scratch(t);
  const run = spawnSync('/bin/sh', [SCRIPT, dirs.checkout], { env: { PATH: process.env.PATH, ...VALID }, encoding: 'utf8' });
  assert.equal(run.status, 2);
  assert.match(run.stderr, /usage: /);
});

test('guard agents check accepts the generated agents.toml', needsGuard, (t) => {
  for (const env of [
    VALID,
    { ...VALID, GUARD_AGENT_RUNTIME: 'mini-swe-agent', GUARD_AGENT_MODEL: 'openai/gpt-5', GUARD_AGENT_BUDGET_USD: '2.5', GUARD_AGENT_HOST_SLOTS: '4' },
    { ...VALID, GUARD_AGENT_RUNTIME: 'codex', GUARD_AGENT_MODEL: 'openai/gpt-5' },
  ]) {
    const dirs = scratch(t);
    assert.equal(render(dirs, env).status, 0);
    const check = spawnSync(GUARD_BIN, ['agents', 'check'], {
      cwd: dirs.checkout,
      env: { PATH: process.env.PATH, GUARD_AGENTS_TOML: join(dirs.out, 'agents.toml') },
      encoding: 'utf8',
    });
    assert.equal(check.status, 0, check.stderr);
    assert.match(check.stdout, /agents\.toml ok \(2 agents; /);
  }
});

for (const mode of ['shadow', 'active']) {
  test(`guard's thresholds parser accepts the generated ${mode} file`, needsGuard, (t) => {
    const dirs = scratch(t);
    assert.equal(render(dirs, { ...VALID, GUARD_THRESHOLDS_MODE: mode }).status, 0);
    // `guard status --integrations` loads thresholds.toml with the parser
    // guard serve uses and reports the mode it read, or the parse error.
    writeFileSync(
      join(dirs.checkout, 'target.toml'),
      'version = 1\n\n[app]\nname = "probe"\nbase_url = "http://localhost:3000"\n\n[areas.core]\ndescription = "Everything"\npaths = ["src/**"]\n',
    );
    const status = spawnSync(GUARD_BIN, ['status', '--integrations', '--json'], {
      cwd: dirs.checkout,
      env: { PATH: process.env.PATH, HOME: dirs.dir, GUARD_THRESHOLDS: join(dirs.out, 'thresholds.toml') },
      encoding: 'utf8',
    });
    assert.equal(status.status, 0, status.stderr);
    const gate = JSON.parse(status.stdout).integrations.find((entry) => entry.id === 'gatekeeper');
    assert.ok(gate, 'the gatekeeper entry is reported');
    assert.doesNotMatch(gate.detail, /invalid thresholds/);
    assert.ok(gate.detail.includes(join(dirs.out, 'thresholds.toml')), gate.detail);
    assert.match(gate.detail, new RegExp(`\\b${mode}\\b`, 'i'));
  });
}
